const body = $input.first().json.body || $input.first().json;
const title = body.title || '';
const slug = body.slug || '';
const summary = (body.summary || body.excerpt || '').substring(0, 300);
const rating = body.rating || '';
const price = body.price || '';
const featuredImage = body.featuredImage || '';
const affiliateUrl = body.affiliateUrl || '';
const videoUrl = body.videoUrl || '';
const articleUrl = 'https://kaoshop-omega.vercel.app/article/' + slug;

return [{ json: { title, slug, articleUrl, featuredImage, affiliateUrl, summary, rating, price, videoUrl } }];

const data = $input.first().json;

const prompt = `สร้าง social media content จากสินค้าต่อไปนี้:\n\nชื่อสินค้า: ${data.title}\nสรุป: ${data.summary || ''}\nคะแนน: ${data.rating}/5\nราคา: ฿${data.price || 'ไม่ระบุ'}\nลิงก์บทความ: ${data.articleUrl}\n${data.affiliateUrl ? 'ลิงก์ซื้อสินค้า: ' + data.affiliateUrl : ''}\n\nส่งกลับเป็น JSON เท่านั้น:\n{\n  "fbCaption": "caption Facebook ภาษาไทย 100-150 คำ เน้นข้อดีสินค้า ทำให้น่าซื้อ + hashtag 5-8 ตัวท้ายข้อความ",\n  "lineMessage": "ข้อความ Line กระชับไม่เกิน 100 ตัวอักษร + emoji + CTA"\n}`;

const openAIPayload = {
  model: 'gpt-4o-mini',
  response_format: { type: 'json_object' },
  messages: [
    {
      role: 'system',
      content: 'คุณเป็น Social Media Manager ผู้เชี่ยวชาญ content ภาษาไทยสำหรับร้านรีวิวสินค้า ตอบกลับเป็น JSON เท่านั้น'
    },
    {
      role: 'user',
      content: prompt
    }
  ]
};

return [{ json: { openAIPayload, ...data } }];

const gpt = $input.first().json;
const prepData = $('เตรียม Content').first().json;

let fbCaption = '';
let lineMessage = '';

try {
  const content = gpt.choices[0].message.content;
  const parsed = JSON.parse(content);
  fbCaption = parsed.fbCaption || '';
  lineMessage = parsed.lineMessage || '';
} catch(e) {
  // fallback ถ้า GPT ไม่ส่ง JSON ถูกต้อง
  fbCaption = '\ud83d\uded2 ' + prepData.title + (prepData.rating ? '\n\n\u2b50 ' + prepData.rating + '/5' : '') + '\n\n\ud83d\udcd6 ' + prepData.articleUrl;
  lineMessage = '\ud83c\udd95 ' + prepData.title.substring(0, 60) + '... \ud83d\udc49 ' + prepData.articleUrl;
}

const heroImage = prepData.featuredImage || 'https://placehold.co/800x520/FF6B00/ffffff?text=KaoShop';

const linePayload = {
  messages: [
    {
      type: 'flex',
      altText: lineMessage || ('\ud83d\udccc \u0e1a\u0e17\u0e04\u0e27\u0e32\u0e21\u0e43\u0e2b\u0e21\u0e48: ' + prepData.title),
      contents: {
        type: 'bubble',
        hero: {
          type: 'image',
          url: heroImage,
          size: 'full',
          aspectRatio: '20:13',
          aspectMode: 'cover',
          action: { type: 'uri', uri: prepData.articleUrl }
        },
        body: {
          type: 'box',
          layout: 'vertical',
          contents: [
            { type: 'text', text: '\ud83c\udd95 \u0e1a\u0e17\u0e04\u0e27\u0e32\u0e21\u0e43\u0e2b\u0e21\u0e48!', weight: 'bold', color: '#1DB446', size: 'sm' },
            { type: 'text', text: prepData.title, weight: 'bold', size: 'xl', margin: 'md', wrap: true },
            prepData.rating ? { type: 'text', text: '\u2b50 ' + prepData.rating + '/5', size: 'sm', color: '#aaaaaa', margin: 'md' } : null,
            lineMessage ? { type: 'text', text: lineMessage, size: 'sm', color: '#555555', margin: 'md', wrap: true } : null
          ].filter(Boolean)
        },
        footer: {
          type: 'box',
          layout: 'vertical',
          spacing: 'sm',
          contents: [
            {
              type: 'button',
              style: 'primary',
              height: 'sm',
              color: '#FF6B00',
              action: { type: 'uri', label: '\ud83d\udcd6 \u0e2d\u0e48\u0e32\u0e19\u0e23\u0e35\u0e27\u0e34\u0e27', uri: prepData.articleUrl }
            },
            prepData.affiliateUrl ? {
              type: 'button',
              style: 'secondary',
              height: 'sm',
              action: { type: 'uri', label: '\ud83d\udecd \u0e0b\u0e37\u0e49\u0e2d\u0e40\u0e25\u0e22', uri: prepData.affiliateUrl }
            } : null
          ].filter(Boolean)
        }
      }
    }
  ]
};

return [{ json: { ...prepData, fbCaption, lineMessage, linePayload } }];
